{
  "Reciprocity": {"Explanation": "The email offers a sense of safety and security by implying that the recipient will receive help if their account is compromised. This creates the illusion of favor and indebtedness."},
  "Scarcity": {"Explanation": "The email creates urgency by implying that the recipient must act now to protect their account. The phrase 'if this was you' and the mention of a malicious user create a sense of vulnerability and urgency."},
  "Authority": {"Explanation": "The email claims authority by mentioning the PayPal brand name and implying that the recipient's security is important to the company. This builds trust and credibility."},
  "Commitment/Consistency": {"Explanation": "The email references the recipient's prior behavior of signing up for a PayPal account to push further action. This creates a sense of commitment and consistency, making it more likely for the recipient to take action."},
  "Liking": {"Explanation": "The email uses personalization and familiarity by addressing the recipient by name and mentioning their country of residence. This builds rapport and makes the recipient feel like they are being treated individually."},
  "Social proof": {"Explanation": "The email does not contain any social proof elements."}
}

